    const isSpawn = `${x},${z}` === `${C.PLAYER.startPos.x},${C.PLAYER.startPos.z}`;
    if (!isWall && !isBorder && !isSpawn) {
      occupied.add(`${x},${z}`);
      return { x, z };
    }
  }
  return [];
};

// WHY: constrói o nível completo
const buildLevel = () => {
  let grid = RAW_MAP.map(normalizeRow);
  grid = padGrid(grid);

  // WHY: valida o spawn
  const spawnX = C.PLAYER.startPos.x;
  const spawnZ = C.PLAYER.startPos.z;
  if (grid[spawnZ][spawnX] === C.TILES.WALL) {
    throw new Error('Spawn em parede!');
  }
  const neighbors = [
    grid[spawnZ - 1][spawnX],
    grid[spawnZ + 1][spawnX],
    grid[spawnZ][spawnX - 1],
    grid[spawnZ][spawnX + 1],
  ];
  for (const n of neighbors) {
    if (n === C.TILES.WALL) throw new Error('Spawn cercado por parede!');
  }

  const pickups = SPREAD_PICKUPS(grid, 20, ['H', 'A', 'W']);
  const doors = SPREAD_PICKUPS(grid, 8, ['D']);
  const exits = SPREAD_PICKUPS(grid, 2, ['S']);
  const secrets = SPREAD_PICKUPS(grid, 1, ['!']);
  const torches = PLACE_TORCHES(grid, 10);
  const lava = SPREAD_PICKUPS(grid, 5, ['L']);

  for (const p of pickups) grid[p.z][p.x] = p.type;
  for (const d of doors) grid[d.z][d.x] = d.type;
  for (const e of exits) grid[e.z][e.x] = e.type;
  for (const s of secrets) grid[s.z][s.x] = s.type;
  for (const t of torches) grid[t.z][t.x] = C.TILES.TORCH;
  for (const l of lava) grid[l.z][l.x] = C.TILES.LAVA;

  const playerSpawn = { x: spawnX, z: spawnZ, yaw: Math.PI / 2 };
  const exitsList = exits.map((e) => ({ x: e.x, z: e.z }));
  const secretsList = secrets.map((s) => ({ x: s.x, z: s.z }));
  const doorsList = doors.map((d) => ({ x: d.x, z: d.z, state: 'closed' }));
  const lavaList = lava.map((l) => ({ x: l.x, z: l.z }));

  return { grid, zones: ZONES, playerSpawn, exits: exitsList, secrets: secretsList, torches, pickups, doors: doorsList, lava: lavaList };
};

// WHY: verifica se uma célula é parede
const isWall = (grid, x, z) => {
  if (z < 0 || z >= grid.length || x < 0 || x >= grid[0].length) return true;
  return grid[z][x] === C.TILES.WALL;
};

// WHY: verifica se um tile é sólido (parede ou porta fechada)
const isSolidTile = (ch) => {
  return ch === C.TILES.WALL || ch === C.TILES.DOOR;
};

// WHY: retorna o tile em uma posição
const cellAt = (grid, x, z) => {
  if (z < 0 || z >= grid.length || x < 0 || x >= grid[0].length) return C.TILES.WALL;
  return grid[z][x];
};

// WHY: raycasting DDA para verificar linha de visão
const hasLineOfSight = (grid, x0, z0, x1, z1, doors = []) => {
  let dx = x1 - x0;
  let dz = z1 - z0;
  const steps = Math.max(Math.abs(dx), Math.abs(dz));
  if (steps === 0) return true;

  const sx = dx / steps;
  const sz = dz / steps;

  let curX = x0;
  let curZ = z0;
  for (let i = 0; i < steps; i++) {
    const tx = Math.floor(curX + 0.5);
    const tz = Math.floor(curZ + 0.5);
    if (tx < 0 || tx >= grid[0].length || tz < 0 || tz >= grid.length) return false;
    const tile = grid[tz][tx];
    if (tile === C.TILES.WALL) return false;
    const doorIdx = doors.findIndex((d) => d.x === tx && d.z === tz);
    if (doorIdx !== -1 && doors[doorIdx].state === 'closed') return false;
    curX += sx;
    curZ += sz;
  }
  return true;
};

export {
  buildLevel,
  isWall,
  isSolidTile,
  cellAt,
  hasLineOfSight,
  RAW_MAP,
  ZONES,
};

// js/move.js — física pura para DOOM clone
// Sem dependências, testável em node

import C from './constants.js';
import { R_y, clamp } from './utils.js';

// WHY: aplica gravidade ao vetor de velocidade
const applyGravity = (vel, dt) => {
  vel.y += C.PHYSICS.gravity * dt;
  vel.y = clamp(vel.y, C.PHYSICS.maxFall, C.PHYSICS.gravity * 0);
  return vel;
};

// WHY: aplica atrito ou resistência do ar
const applyFriction = (vel, dt, onGround) => {
  if (onGround) {
    vel.x *= 1 - C.PHYSICS.friction * dt;
    vel.z *= 1 - C.PHYSICS.friction * dt;
  } else {
    vel.x *= 1 - C.PHYSICS.airResist * dt;
    vel.z *= 1 - C.PHYSICS.airResist * dt;
  }
  return vel;
};

// WHY: acelera o jogador na direção desejada
const accelerate = (vel, wishdir, accel, dt) => {
  vel.x += wishdir.x * accel * dt;
  vel.z += wishdir.z * accel * dt;
  return vel;
};

// WHY: move e resolve colisão AABB por eixo
const moveAxis = (pos, vel, axis, dt, grid, radius) => {
  const newVel = { ...vel };
  const newPos = { ...pos };

  const oldX = pos[axis];
  const oldY = pos[axis === 'x' ? 'z' : 'x'];
  const newX = pos[axis === 'x' ? 'x' : 'z'] + vel[axis] * dt;
  const newY = pos[axis === 'x' ? 'z' : 'x'] + vel[axis === 'x' ? 'z' : 'x'] * dt;

  if (axis === 'x') {
    const xMin = oldX - radius;
    const xMax = newX + radius;
    const yMin = oldY - radius;
    const yMax = newY + radius;

    const hitWallLeft = grid[Math.floor(yMin)][Math.floor(xMin)] === C.TILES.WALL;
    const hitWallRight = grid[Math.floor(yMax)][Math.floor(xMax)] === C.TILES.WALL;
    const hitWallTop = grid[Math.floor(yMin)][Math.floor(xMin + 1)] === C.TILES.WALL || grid[Math.floor(yMin)][Math.floor(xMax - 1)] === C.TILES.WALL;
    const hitWallBottom = grid[Math.floor(yMax)][Math.floor(xMin + 1)] === C.TILES.WALL || grid[Math.floor(yMax)][Math.floor(xMax - 1)] === C.TILES.WALL;

    if (hitWallLeft || hitWallRight || hitWallTop || hitWallBottom) {
      newVel[axis] = 0;
      newPos[axis] = oldX + vel[axis] * dt;
      newPos[axis] = clamp(newPos[axis], oldX - radius, oldX + radius);
    }
  } else {
    const zMin = oldY - radius;
    const zMax = newY + radius;
    const xMin = oldX - radius;
    const xMax = newX + radius;

    const hitWallFront = grid[Math.floor(zMin)][Math.floor(xMin)] === C.TILES.WALL;
    const hitWallBack = grid[Math.floor(zMax)][Math.floor(xMax)] === C.TILES.WALL;
    const hitWallLeft = grid[Math.floor(zMin)][Math.floor(xMin + 1)] === C.TILES.WALL || grid[Math.floor(zMin)][Math.floor(xMax - 1)] === C.TILES.WALL;
    const hitWallRight = grid[Math.floor(zMax)][Math.floor(xMin + 1)] === C.TILES.WALL || grid[Math.floor(zMax)][Math.floor(xMax - 1)] === C.TILES.WALL;

    if (hitWallFront || hitWallBack || hitWallLeft || hitWallRight) {
      newVel[axis] = 0;
      newPos[axis] = oldY + vel[axis] * dt;
      newPos[axis] = clamp(newPos[axis], oldY - radius, oldY + radius);
    }
  }

  const collided = newVel[axis] !== vel[axis];
  return { pos: newPos, vel: newVel, collided };
};

// WHY: aplica pulo quando no chão
const tryJump = (vel, onGround) => {
  if (onGround) vel.y = C.PHYSICS.jumpVel;
  return vel;
};

// WHY: aplica knockback ao jogador
const knockback = (vel, dirX, dirZ, force) => {
  vel.x += dirX * force * C.PHYSICS.BOUNCE;
  vel.z += dirZ * force * C.PHYSICS.BOUNCE;
  return vel;
};

// WHY: calcula dano de splash por distância
const splashDamage = (damage, dist, radius) => {
  if (dist > radius) return 0;
  if (dist === 0) return damage;
  return damage * (1 - dist / radius);
};

// WHY: bobbing da câmera
const cameraBob = (time, moving, speed) => {
  const bobAmp = C.PHYSICS.bobAmp;
  const bobFreq = C.PHYSICS.bobFreq;
  if (!moving) return { x: 0, y: 0 };
  return {
    x: Math.sin(time * bobFreq) * bobAmp,
    y: Math.sin(time * bobFreq * 2) * bobAmp * 0.5,
  };
};

export {
  applyGravity,
  applyFriction,
  accelerate,
  moveAxis,
  tryJump,
  knockback,
  splashDamage,
  cameraBob,
};

