// tests/map.test.mjs — TDD para map.js

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import C from '../js/constants.js';
import * as map from '../js/map.js';

describe('map', () => {
  describe('normalizeRow', () => {
    it('normaliza linha curta para 44 chars', () => {
      const row = 'hello';
      const result = map.normalizeRow(row);
      assert.equal(result.length, C.MAP.gridW);
    });

    it('não altera linha completa', () => {
      const row = '######################################';
      const result = map.normalizeRow(row);
      assert.equal(result, row);
    });
  });

  describe('padGrid', () => {
    it('garante todas as linhas com mesmo comprimento', () => {
      const grid = ['a', 'bb', 'ccc'];
      const padded = map.padGrid(grid);
      const len = padded[0].length;
      for (const row of padded) {
        assert.equal(row.length, len);
      }
    });
  });

  describe('buildLevel', () => {
    it('retorna grid de 36x44 normalizado', () => {
      const level = map.buildLevel();
      assert.equal(level.grid.length, C.MAP.gridH);
      for (const row of level.grid) {
        assert.equal(row.length, C.MAP.gridW);
      }
    });

    it('borda superior é toda #', () => {
      const level = map.buildLevel();
      for (let x = 0; x < C.MAP.gridW; x++) {
        assert.equal(level.grid[0][x], '#');
      }
    });

    it('borda inferior é toda #', () => {
      const level = map.buildLevel();
      for (let x = 0; x < C.MAP.gridW; x++) {
        assert.equal(level.grid[C.MAP.gridH - 1][x], '#');
      }
    });

    it('borda esquerda é toda #', () => {
      const level = map.buildLevel();
      for (let z = 0; z < C.MAP.gridH; z++) {
        assert.equal(level.grid[z][0], '#');
      }
    });

    it('borda direita é toda #', () => {
      const level = map.buildLevel();
      for (let z = 0; z < C.MAP.gridH; z++) {
        assert.equal(level.grid[z][C.MAP.gridW - 1], '#');
      }
    });

    it('spawn (18,22) é floor e 4 vizinhos não parede', () => {
      const level = map.buildLevel();
      const cell = level.grid[22][18];
      assert.equal(cell, C.TILES.FLOOR, 'Spawn não é floor');

      const neighbors = [
        level.grid[21][18], // norte
        level.grid[23][18], // sul
        level.grid[22][17], // oeste
        level.grid[22][19], // leste
      ];
      for (const n of neighbors) {
        assert.notEqual(n, C.TILES.WALL, `Vizinho spawn ${n} é parede`);
      }
    });

    it('todos os tiles são válidos', () => {
      const level = map.buildLevel();
      const valid = new Set(Object.values(C.TILES));
      for (let z = 0; z < C.MAP.gridH; z++) {
        for (let x = 0; x < C.MAP.gridW; x++) {
          assert.ok(
            valid.has(level.grid[z][x]),
            `Tile inválido em (${x},${z}): ${level.grid[z][x]}`
          );
        }
      }
    });

    it('exits, secrets, torches e pickups não na borda', () => {
      const level = map.buildLevel();
      const items = [
        ...level.exits,
        ...level.secrets,
        ...level.torches,
        ...level.pickups,
      ];
      for (const item of items) {
        assert.ok(
          item.x > 0 && item.x < C.MAP.gridW - 1,
          `${item.type} em x=0 ou x=${C.MAP.gridW-1}: (${item.x},${item.z})`
        );
        assert.ok(
          item.z > 0 && item.z < C.MAP.gridH - 1,
          `${item.type} em z=0 ou z=${C.MAP.gridH-1}: (${item.x},${item.z})`
        );
      }
    });

    it('retorna 6 zonas', () => {
      const level = map.buildLevel();
      assert.equal(level.zones.length, 6);
    });

    it('retorna ~20 pickups', () => {
      const level = map.buildLevel();
      assert.equal(level.pickups.length, 20);
    });

    it('retorna 8 doors', () => {
      const level = map.buildLevel();
      assert.equal(level.doors.length, 8);
    });

    it('retorna 2 exits', () => {
      const level = map.buildLevel();
      assert.equal(level.exits.length, 2);
    });

    it('retorna 1 secret', () => {
      const level = map.buildLevel();
      assert.equal(level.secrets.length, 1);
    });

    it('retorna ~10 torches', () => {
      const level = map.buildLevel();
      assert.equal(level.torches.length, 10);
    });

    it('retorna lava pool', () => {
      const level = map.buildLevel();
      assert.ok(level.lava.length > 0, 'Sem lava no mapa');
    });

    it('playerSpawn tem yaw', () => {
      const level = map.buildLevel();
      assert.ok('yaw' in level.playerSpawn);
    });

    it('doors têm state closed', () => {
      const level = map.buildLevel();
      for (const d of level.doors) {
        assert.equal(d.state, 'closed');
      }
    });
  });

  describe('isWall', () => {
    it('retorna true para parede', () => {
      const level = map.buildLevel();
      assert.equal(map.isWall(level.grid, 5, 5), true);
    });

    it('retorna false para floor', () => {
      const level = map.buildLevel();
      assert.equal(map.isWall(level.grid, 18, 22), false);
    });

    it('retorna true para fora do grid', () => {
      assert.equal(map.isWall([['#']], -1, 0), true);
      assert.equal(map.isWall([['#']], 0, -1), true);
    });
  });

  describe('isSolidTile', () => {
    it('parede é sólido', () => {
      assert.equal(map.isSolidTile(C.TILES.WALL), true);
    });

    it('porta é sólido', () => {
      assert.equal(map.isSolidTile(C.TILES.DOOR), true);
    });

    it('floor não é sólido', () => {
      assert.equal(map.isSolidTile(C.TILES.FLOOR), false);
    });
  });

  describe('cellAt', () => {
    it('retorna tile em posição válida', () => {
      const level = map.buildLevel();
      const tile = map.cellAt(level.grid, 18, 22);
      assert.equal(tile, C.TILES.FLOOR);
    });

    it('retorna WALL fora do grid', () => {
      assert.equal(map.cellAt([['#']], -1, 0), C.TILES.WALL);
    });
  });

  describe('hasLineOfSight', () => {
    it('caminho claro retorna true', () => {
      const grid = [
        ['.', '.', '.', '.', '.'],
        ['.', '.', '.', '.', '.'],
        ['.', '.', '.', '.', '.'],
      ];
      assert.equal(map.hasLineOfSight(grid, 0, 0, 2, 2), true);
    });

    it('parede bloqueia visão', () => {
      const grid = [
        ['.', '.', '.', '.', '.'],
        ['.', '#', '#', '.', '.'],
        ['.', '.', '.', '.', '.'],
      ];
      assert.equal(map.hasLineOfSight(grid, 0, 0, 4, 0), false);
    });

    it('porta fechada bloqueia visão', () => {
      const grid = [
        ['.', '.', '.', '.', '.'],
        ['.', 'D', '.', '.', '.'],
        ['.', '.', '.', '.', '.'],
      ];
      const doors = [{ x: 2, z: 1, state: 'closed' }];
      assert.equal(map.hasLineOfSight(grid, 0, 1, 4, 1, doors), false);
    });

    it('porta aberta permite visão', () => {
      const grid = [
        ['.', '.', '.', '.', '.'],
        ['.', 'D', '.', '.', '.'],
        ['.', '.', '.', '.', '.'],
      ];
      const doors = [{ x: 2, z: 1, state: 'open' }];
      assert.equal(map.hasLineOfSight(grid, 0, 1, 4, 1, doors), true);
    });
  });
});

