import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import C from '../js/constants.js';
import * as move from '../js/move.js';

describe('move', () => {
  describe('applyGravity', () => {
    it('diminui vel.y', () => {
      const vel = { x: 0, y: 0, z: 0 };
      const result = move.applyGravity(vel, C.PHYSICS.step);
      assert.ok(result.y < 0);
    });

    it('clama em maxFall', () => {
      const vel = { x: 0, y: -100, z: 0 };
      const result = move.applyGravity(vel, C.PHYSICS.step * 100);
      assert.equal(result.y, C.PHYSICS.maxFall);
    });
  });

  describe('applyFriction', () => {
    it('reduz velocidade no chão', () => {
      const vel = { x: 5, y: 0, z: 0 };
      const result = move.applyFriction(vel, C.PHYSICS.step, true);
      assert.ok(Math.abs(result.x) < 5);
    });

    it('aplica airResist no ar', () => {
      const vel = { x: 5, y: 0, z: 0 };
      const result = move.applyFriction(vel, C.PHYSICS.step, false);
      assert.ok(Math.abs(result.x) < 5);
    });
  });

  describe('accelerate', () => {
    it('acelera na direção do wishdir', () => {
      const vel = { x: 0, y: 0, z: 0 };
      const wishdir = { x: 1, z: 0 };
      const result = move.accelerate(vel, wishdir, C.PHYSICS.accel, C.PHYSICS.step);
      assert.ok(result.x > 0);
    });

    it('acelera no eixo z', () => {
      const vel = { x: 0, y: 0, z: 0 };
      const wishdir = { x: 0, z: 1 };
      const result = move.accelerate(vel, wishdir, C.PHYSICS.accel, C.PHYSICS.step);
      assert.ok(result.z > 0);
    });
  });

  describe('moveAxis', () => {
    it('move sem colisão', () => {
      const grid = [
        ['.', '.', '.'],
        ['.', '.', '.'],
        ['.', '.', '.'],
      ];
      const pos = { x: 1, y: 1 };
      const vel = { x: 1, y: 0 };
      const result = move.moveAxis(pos, vel, 'x', C.PHYSICS.step, grid, 0.5);
      assert.ok(result.pos.x > 1);
      assert.equal(result.collided, false);
    });

    it('para velocidade no eixo colidido', () => {
      const grid = [
        ['#', '.', '#'],
        ['#', '.', '#'],
        ['#', '.', '#'],
      ];
      const pos = { x: 1, y: 1 };
      const vel = { x: 3, y: 0 };
      const result = move.moveAxis(pos, vel, 'x', C.PHYSICS.step, grid, 0.5);
      assert.equal(result.vel.x, 0);
    });

    it('clama posição no eixo colidido', () => {
      const grid = [
        ['#', '.', '#'],
        ['#', '.', '#'],
        ['#', '.', '#'],
      ];
      const pos = { x: 1, y: 1 };
      const vel = { x: 3, y: 0 };
      const result = move.moveAxis(pos, vel, 'x', C.PHYSICS.step, grid, 0.5);
      assert.equal(result.pos.x, 1);
    });
  });

  describe('tryJump', () => {
    it('seta vel.y=jumpVel quando onGround', () => {
      const vel = { x: 0, y: 0, z: 0 };
      const result = move.tryJump(vel, true);
      assert.equal(result.y, C.PHYSICS.jumpVel);
    });

    it('não muda vel.y quando no ar', () => {
      const vel = { x: 0, y: -10, z: 0 };
      const result = move.tryJump(vel, false);
      assert.equal(result.y, -10);
    });
  });

  describe('knockback', () => {
    it('adiciona força ao vetor', () => {
      const vel = { x: 0, y: 0, z: 0 };
      const result = move.knockback(vel, 1, 0, 10);
      assert.ok(result.x > 0);
    });
  });

  describe('splashDamage', () => {
    it('dist 0 = dano total', () => {
      assert.equal(move.splashDamage(100, 0, 5), 100);
    });

    it('dist = radius = 0 dano', () => {
      assert.equal(move.splashDamage(100, 5, 5), 0);
    });

    it('dist > radius = 0 dano', () => {
      assert.equal(move.splashDamage(100, 6, 5), 0);
    });

    it('dano parcial no meio', () => {
      const dmg = move.splashDamage(100, 2.5, 5);
      assert.ok(dmg > 0);
      assert.ok(dmg < 100);
    });
  });

  describe('cameraBob', () => {
    it('retorna 0,0 quando !moving', () => {
      const result = move.cameraBob(0, false, 1);
      assert.equal(result.x, 0);
      assert.equal(result.y, 0);
    });

    it('retorna valores quando moving', () => {
      const result = move.cameraBob(0, true, 1);
      assert.ok(Math.abs(result.x) > 0);
      assert.ok(Math.abs(result.y) > 0);
    });
  });
});

