// WHY: normaliza cada linha do mapa bruto para gridW chars
const normalizeRow = (row) => {
  return row.padEnd(C.MAP.gridW).slice(0, C.MAP.gridW);
};

// WHY: garante que todas as linhas tenham o mesmo comprimento
const padGrid = (grid) => {
  const maxLen = Math.max(...grid.map((r) => r.length));
  return grid.map((row) => normalizeRow(row.padEnd(maxLen)));
};

