// WHY: espalha pickups aleatoriamente na zona segura
const SPREAD_PICKUPS = (grid, count, types) => {
  const spawns = { x: C.PLAYER.startPos.x, z: C.PLAYER.startPos.z };
  const occupied = new Set();
  occupied.add(`${spawns.x},${spawns.z}`);

  const tryPlace = () => {
    let x, z;
    do {
