  const newPos = { ...pos };

  // WHY: eixo complementar (y é o eixo "outro" no teste)
  const other = axis === 'x' ? 'y' : 'x';
  const oldMain = pos[axis];
  const oldOther = pos[other];
  const newMain = pos[axis] + vel[axis] * dt;
  const newOther = pos[other] + vel[other] * dt;

  if (axis === 'x') {
    const xMin = Math.floor(oldMain - radius);
    const xMax = Math.floor(newMain + radius);
    const yMin = Math.floor(oldOther - radius);
    const yMax = Math.floor(newOther + radius);

    const hitLeft = grid[yMin][xMin] === C.TILES.WALL;
    const hitRight = grid[yMax][xMax] === C.TILES.WALL;
    const hitTop = grid[yMin][xMin + 1] === C.TILES.WALL || grid[yMin][xMax - 1] === C.TILES.WALL;
    const hitBottom = grid[yMax][xMin + 1] === C.TILES.WALL || grid[yMax][xMax - 1] === C.TILES.WALL;

    if (hitLeft || hitRight || hitTop || hitBottom) {
      newVel.x = 0;
      newPos.x = oldMain + vel.x * dt;
      newPos.x = clamp(newPos.x, oldMain - radius, oldMain + radius);
    }
  } else {
