    const zMin = Math.floor(oldOther - radius);
    const zMax = Math.floor(newOther + radius);
    const xMin = Math.floor(oldMain - radius);
    const xMax = Math.floor(newMain + radius);

    const hitFront = grid[zMin][xMin] === C.TILES.WALL;
    const hitBack = grid[zMax][xMax] === C.TILES.WALL;
    const hitLeft = grid[zMin][xMin + 1] === C.TILES.WALL || grid[zMin][xMax - 1] === C.TILES.WALL;
    const hitRight = grid[zMax][xMin + 1] === C.TILES.WALL || grid[zMax][xMax - 1] === C.TILES.WALL;

    if (hitFront || hitBack || hitLeft || hitRight) {
      newVel.z = 0;
      newPos.z = oldOther + vel[other] * dt;
      newPos.z = clamp(newPos.z, oldOther - radius, oldOther + radius);
    }
  }

  const collided = newVel[axis] !== vel[axis];
  return { pos: newPos, vel: newVel, collided };
};

